G(0,()=>{const r=ch('B ≠ 0',['A ≠ 0','A ≠ 0 и B ≠ 0','B > 0']);
return {type:'choice',q:`Как звучит правило: дробь ${M(F('A','B'))} имеет смысл, когда…`,...r,
short:'Запрещён только ноль в знаменателе.',
explain:`На ноль делить нельзя — это единственный запрет. Поэтому дробь имеет смысл, когда <b>B ≠ 0</b>.<br>Числитель A может быть любым, даже нулём: ${F(0,5)} = 0 — нормальная дробь. И B может быть отрицательным: ${F(6,'−2')} = −3.`,
explain2:`Представь: A пицц делим на B друзей. Ноль пицц на 5 друзей — можно (каждому по нулю 😢). А 5 пицц на 0 друзей — бессмыслица. Поэтому запрет только на <b>B = 0</b>.`};},false,true);
G(0,()=>{const a=R(2,9),b=R(2,5),c=R(2,7);const right=`${F(a,'x − '+b)} = ${c}`;
const r=ch(right,[`${F('x',2)} + ${F('x',3)} = ${c}`,`${F(a,b)}x = ${c}`,`x² − ${b} = ${F(a,c)}`]);
return {type:'choice',q:'Какое из уравнений — <b>дробно-рациональное</b>?',opts:r.opts.map(M),ans:r.ans,
short:'Переменная стоит в знаменателе только у одного уравнения.',
explain:`Дробно-рациональное — это уравнение, где <b>переменная стоит в знаменателе</b>. Только в ${M(right)} x внизу.<br>В остальных внизу просто числа (2, 3, ${b}, ${c}) — это обычные «целые» уравнения, хоть в них и есть дроби.`,
explain2:`Смотри не на то, есть ли черта дроби, а на то, <b>кто стоит под чертой</b>. Число под чертой — ничего страшного. x под чертой — значит, появятся запрещённые x, и уравнение дробно-рациональное.`};},false,true);
G(0,()=>{let p,q;do{p=nz(-9,9);q=nz(-9,9);}while(p===-q);const a=R(1,9);
return {type:'set',q:`При каких x выражение ${M(F(a,`(${xp(-p)})(${xp(q)})`))} <b>не имеет смысла</b>? Запиши все такие x.`,ans:[p,-q],ph:'например: −3; 5',
hint:'Ищи, когда знаменатель равен нулю. Произведение равно нулю, когда хотя бы один множитель равен нулю.',
short:`Знаменатель равен 0 при x = ${N(p)} и при x = ${N(-q)}.`,
explain:`Нельзя, чтобы <b>знаменатель</b> был равен нулю.<br>Знаменатель — произведение (${xp(-p)})(${xp(q)}). Произведение равно нулю, когда <b>хотя бы один</b> множитель равен нулю:<br>• ${xp(-p)} = 0 → x = ${N(p)};<br>• ${xp(q)} = 0 → x = ${N(-q)}.<br>Ответ: <b>${N(p)}; ${N(-q)}</b>. Числитель ${a} здесь ни при чём.`,
explain2:`Проверь подстановкой. x = ${N(p)}: первая скобка ${N(p)} ${p>0?'−':'+'} ${Math.abs(p)} = 0 → внизу 0 → «Error». x = ${N(-q)}: вторая скобка ${N(-q)} ${q>0?'+':'−'} ${Math.abs(q)} = 0 → снова «Error». Других таких x нет.`};});
G(0,()=>{const k=R(2,9);const sq=Math.random()<0.6;const den=sq?`x² − ${k*k}`:`x² − ${k}x`;const ans=sq?[k,-k]:[0,k];
return {type:'set',q:`Найди все x, при которых дробь ${M(F(R(1,9),den))} не имеет смысла.`,ans,ph:'например: −3; 5',
hint:sq?'Разложи знаменатель по формуле разности квадратов.':'Вынеси x за скобки.',
short:sq?`x² − ${k*k} = (x − ${k})(x + ${k}) = 0 при x = ±${k}.`:`x² − ${k}x = x(x − ${k}) = 0 при x = 0 и x = ${k}.`,
explain:sq?`Знаменатель x² − ${k*k} = 0. Разложим: x² − ${k}² = (x − ${k})(x + ${k}).<br>Ноль, когда x = ${k} <b>или</b> x = −${k}.<br>Ответ: <b>${k}; −${k}</b>.<div class="box err"><b>Частая ошибка</b>Написать только x = ${k} и забыть про −${k}: (−${k})² = ${k*k} тоже!</div>`:
`Знаменатель x² − ${k}x = 0. Выносим x: x(x − ${k}) = 0.<br>Произведение равно нулю, когда x = 0 <b>или</b> x − ${k} = 0, то есть x = ${k}.<br>Ответ: <b>0; ${k}</b>.<div class="box err"><b>Частая ошибка</b>Поделить на x и «потерять» x = 0.</div>`,
explain2:sq?`Подставь: ${k}² − ${k*k} = 0 и (−${k})² − ${k*k} = ${k*k} − ${k*k} = 0. Оба числа обнуляют знаменатель — оба запрещены.`:`Подставь: 0² − ${k}·0 = 0 и ${k}² − ${k}·${k} = 0. Оба числа обнуляют знаменатель.`};});
G(0,()=>{let b,d,a,c;do{b=nz(-8,8);d=nz(-8,8);}while(b===d||b===-d);a=nz(-9,9);c=R(1,9);
const vals=[b,-d,-b,d];const o=shuffle(vals.map((v,i)=>({v,i})));
return {type:'multi',q:`Какие числа <b>нельзя</b> подставлять в уравнение ${M(F(xp(a),xp(-b))+' = '+F(c,xp(d)))}? Выбери все.`,opts:o.map(x=>`x = ${N(x.v)}`),ans:o.map((x,j)=>x.i<2?j:-1).filter(j=>j>=0),
short:`Знаменатели ${xp(-b)} и ${xp(d)} обнуляются при x = ${N(b)} и x = ${N(-d)}.`,
explain:`Смотрим только на <b>знаменатели</b>:<br>• ${xp(-b)} = 0 → x = ${N(b)};<br>• ${xp(d)} = 0 → x = ${N(-d)}.<br>Значит, нельзя: <b>x = ${N(b)}</b> и <b>x = ${N(-d)}</b>.<br>Числа ${N(-b)} и ${N(d)} — ловушка: это те же числа с «перевёрнутым» знаком. Подставь x = ${N(-b)}: ${N(-b)} ${b>0?'−':'+'} ${Math.abs(b)} = ${N(-2*b)} ≠ 0 — можно.`,
explain2:`Правило «ищи число, которое делает скобку нулём»: в скобке (x − 5) это 5 (знак меняется!), в скобке (x + 5) это −5. Здесь: (${xp(-b)}) → ${N(b)}, (${xp(d)}) → ${N(-d)}.`};});

/* L1 — дробь равна нулю */
G(1,()=>{const r=ch(`A = 0 и B ≠ 0`,['B = 0','A = 0, а B — любое','A = B']);
return {type:'choice',q:`Допиши правило: ${M(F('A','B')+' = 0')} тогда и только тогда, когда…`,...r,
short:'Ноль сверху, но не ноль снизу.',
explain:`Дробь равна нулю, когда <b>числитель A = 0</b>, а <b>знаменатель B ≠ 0</b>.<br>«A = 0, а B — любое» — почти правильно, но если и B = 0, то получится ${F(0,0)} — это не число, а бессмыслица.<br>«B = 0» — наоборот, тогда дробь вообще не существует.`,
explain2:`Проверь на числах: ${F(0,7)} = 0 ✅ (сверху 0, снизу не 0). ${F(5,7)} ≠ 0 (сверху не 0). ${F(0,0)} — не существует. Вывод: нужно и «сверху 0», и «снизу не 0».`};},false,true);
G(1,()=>{let a,b;do{a=nz(-9,9);b=nz(-9,9);}while(a===-b);
return {type:'set',q:`Реши уравнение ${M(F(xp(-a),xp(b))+' = 0')}.`,ans:[a],ph:'корни через «;» или ∅',
short:`Числитель ${xp(-a)} = 0 → x = ${N(a)}; знаменатель при этом ${N(a+b)} ≠ 0.`,
explain:`Дробь равна нулю, когда числитель равен нулю, а знаменатель — нет.<br>1) ${xp(-a)} = 0 → x = ${N(a)}.<br>2) Проверка знаменателя: ${N(a)} ${b>0?'+':'−'} ${Math.abs(b)} = ${N(a+b)} ≠ 0 ✅.<br>Ответ: <b>${N(a)}</b>.`,
explain2:`Подставь x = ${N(a)}: ${F(N(a)+(a>0?' − ':' + ')+Math.abs(a),N(a)+(b>0?' + ':' − ')+Math.abs(b))} = ${F(0,N(a+b))} = 0 ✅. Знаменатель x = ${N(-b)} не трогаем — он запрещён, но в ответ он и не просится.`};});
G(1,()=>{const k=R(1,9),s=pick([1,-1]);   // (x²−k²)/(x − s k) = 0 → x = −s k
const den=xp(-s*k),root=-s*k;
return {type:'set',q:`Реши уравнение ${M(F(`x² − ${k*k}`,den)+' = 0')}.`,ans:[root],ph:'корни через «;» или ∅',
hint:'Числитель = 0 даёт два числа. Но одно из них обнуляет знаменатель.',
short:`x² = ${k*k} → x = ±${k}, но x = ${N(s*k)} обнуляет знаменатель. Ответ: ${N(root)}.`,
explain:`1) Числитель: x² − ${k*k} = 0 → x = ${k} или x = −${k}.<br>2) Знаменатель ${den}: при x = ${N(s*k)} он равен 0 → этот x <b>вычёркиваем</b>.<br>Ответ: <b>${N(root)}</b>.<div class="box err"><b>Ловушка</b>Записать оба корня ±${k}. Подставь x = ${N(s*k)}: получится ${F(0,0)} — такой дроби не существует.</div>`,
explain2:`Другой путь: сократим дробь. ${F(`(x − ${k})(x + ${k})`,den)} = ${xp(s*k)} при x ≠ ${N(s*k)}. Уравнение ${xp(s*k)} = 0 → x = ${N(root)}. Важно: сокращение «помнит», что x ≠ ${N(s*k)}.`};});
G(1,()=>{let a,b;do{a=nz(-7,7);b=nz(-7,7);}while(a===b);
const num=pf([a*b,-(a+b),1]);
return {type:'set',q:`Реши уравнение ${M(F(num,xp(-b))+' = 0')}.`,ans:[a],ph:'корни через «;» или ∅',
hint:`Разложи числитель на множители: подбери два числа, сумма которых ${N(a+b)}, а произведение ${N(a*b)}.`,
short:`${num} = (${xp(-a)})(${xp(-b)}). x = ${N(b)} запрещён, остаётся x = ${N(a)}.`,
explain:`1) Числитель = 0: ${num} = 0. По теореме Виета корни: сумма ${N(a+b)}, произведение ${N(a*b)} → x = ${N(a)} и x = ${N(b)}.<br>2) Знаменатель ${xp(-b)} = 0 при x = ${N(b)} — <b>вычёркиваем</b>.<br>Ответ: <b>${N(a)}</b>.`,
explain2:`Разложим: ${num} = (${xp(-a)})(${xp(-b)}). Дробь ${F(`(${xp(-a)})(${xp(-b)})`,xp(-b))}. При x = ${N(b)} внизу 0 — нельзя. При x = ${N(a)} сверху 0, снизу ${N(a-b)} ≠ 0 — подходит.`};});

/* L2 — пропорция, общий знаменатель */
G(2,()=>{const r=ch(`a·d = b·c`,['a·c = b·d','a + d = b + c',`${F('a','c')} = ${F('b','d')}·2`]);
return {type:'choice',q:`Основное свойство пропорции: если ${M(F('a','b')+' = '+F('c','d'))} (b ≠ 0, d ≠ 0), то…`,...r,
short:'Произведение крайних = произведению средних, «крест-накрест».',
explain:`Умножим обе части на b·d: слева ${F('a','b')}·bd = ad, справа ${F('c','d')}·bd = cb. Получаем <b>a·d = b·c</b> — «крест-накрест».`,
explain2:`Проверь на числах: ${F(2,3)} = ${F(4,6)}. Крест-накрест: 2·6 = 12 и 3·4 = 12 ✅. А «a·c = b·d»: 2·4 = 8, 3·6 = 18 — не равно. Значит, правильно a·d = b·c.`};},false,true);
G(2,()=>{let a,b,p,q,x;for(;;){a=R(1,9);b=R(1,9);p=nz(-8,8);q=nz(-8,8);if(a===b||p===q)continue;const num=a*q-b*p,den=a-b;if(num%den)continue;x=num/den;if(x!==p&&x!==q&&Math.abs(x)<=30)break;}
ok(near(a/(x-p),b/(x-q)),'prop');
return {type:'num',q:`Реши уравнение ${M(F(a,xp(-p))+' = '+F(b,xp(-q)))}.`,ans:x,
hint:'Пропорция: перемножь крест-накрест.',
short:`${a}(${xp(-q)}) = ${b}(${xp(-p)}) → x = ${N(x)}.`,
explain:`ОДЗ: x ≠ ${N(p)}, x ≠ ${N(q)}.<br>Крест-накрест: ${a}(${xp(-q)}) = ${b}(${xp(-p)}).<br>Раскрываем: ${pf([-a*q,a])} = ${pf([-b*p,b])}.<br>Переносим: ${cx(a-b)}x = ${N(a*q-b*p)} → x = <b>${N(x)}</b>.<br>${N(x)} не запрещён ✅.`,
explain2:`Проверка подстановкой: ${F(a,`${N(x)} ${p>0?'−':'+'} ${Math.abs(p)}`)} = ${qh(a,x-p)}, ${F(b,`${N(x)} ${q>0?'−':'+'} ${Math.abs(q)}`)} = ${qh(b,x-q)}. Равны ✅.`};});
G(2,()=>{let a,b,c,x;for(;;){a=nz(-9,9);b=nz(-9,9);c=nz(-5,6);if(c===1)continue;const num=c*b+a,den=c-1;if(num%den)continue;x=num/den;if(x!==b&&Math.abs(x)<=40)break;}
ok(near((x+a)/(x-b),c),'lin');
return {type:'num',q:`Реши уравнение ${M(F(xp(a),xp(-b))+' = '+N(c))}.`,ans:x,
hint:`Умножь обе части на (${xp(-b)}).`,
short:`${xp(a)} = ${pn(c)}(${xp(-b)}) → x = ${N(x)}.`,
explain:`ОДЗ: x ≠ ${N(b)}.<br>Умножаем обе части на (${xp(-b)}): ${xp(a)} = ${N(c)}(${xp(-b)}) = ${pf([-c*b,c])}.<br>Иксы влево, числа вправо: x − ${pn(c)}x = ${N(-c*b)} − ${pn(a)} → ${cx(1-c)}x = ${N(-c*b-a)} → x = <b>${N(x)}</b>.<br>${N(x)} ≠ ${N(b)} ✅.`,
explain2:`Можно как пропорцию: ${F(xp(a),xp(-b))} = ${F(N(c),1)} → (${xp(a)})·1 = ${N(c)}·(${xp(-b)}). Проверка: при x = ${N(x)} дробь равна ${F(N(x+a),N(x-b))} = ${N((x+a)/(x-b))} ✅.`};});
G(2,()=>{let a,b,k,r,c;for(;;){a=R(1,7);b=R(1,7);k=R(1,6);r=nz(-8,8);if(r===k||r===-k)continue;c=(a+b)*r+(a-b)*k;if(c!==0)break;}
ok(near(a/(r-k)+b/(r+k),c/(r*r-k*k)),'cd');
return {type:'num',q:`Реши уравнение ${M(F(a,xp(-k))+' + '+F(b,xp(k))+' = '+F(c,`x² − ${k*k}`))}.`,ans:r,
hint:`Общий знаменатель: x² − ${k*k} = (x − ${k})(x + ${k}).`,
short:`${a}(x + ${k}) + ${b}(x − ${k}) = ${N(c)} → x = ${N(r)}.`,
explain:`ОДЗ: x ≠ ±${k}. Общий знаменатель (x − ${k})(x + ${k}) = x² − ${k*k} — он уже стоит справа!<br>Умножаем всё на него: первая дробь теряет (x − ${k}), но получает (x + ${k}); вторая наоборот:<br>${a}(x + ${k}) + ${b}(x − ${k}) = ${N(c)}<br>${pf([(a-b)*k,a+b])} = ${N(c)} → ${a+b}x = ${N((a+b)*r)} → x = <b>${N(r)}</b>.<br>${N(r)} ≠ ±${k} ✅.`,
explain2:`Почему не (x − ${k})(x + ${k})(x² − ${k*k})? Можно и так, но скобки станут огромными. Сначала разложи все знаменатели на множители и возьми каждый множитель <b>один раз</b>: (x − ${k}) и (x + ${k}). Проверка: при x = ${N(r)}: ${F(a,N(r-k))} + ${F(b,N(r+k))} = ${qh(a*(r+k)+b*(r-k),r*r-k*k)} и ${F(c,N(r*r-k*k))} = ${qh(c,r*r-k*k)} ✅.`};});

/* L3 — посторонние корни */
G(3,()=>{const r=ch('проверить, не обращают ли найденные корни знаменатель в ноль',['проверить, что все корни положительные','разделить ответ на общий знаменатель','ничего — ответ уже готов']);
return {type:'choice',q:'Мы умножили обе части дробного уравнения на общий знаменатель и решили. Что <b>обязательно</b> нужно сделать потом?',...r,
short:'Корни, обнуляющие знаменатель, — посторонние.',
explain:`Когда мы умножаем на выражение с x, при некоторых x мы умножаем <b>на ноль</b>. Из-за этого в ответ могут пролезть <b>посторонние корни</b> — те, при которых исходный знаменатель равен 0. Их нужно найти и вычеркнуть.<br>Отрицательные корни при этом вполне законны (если задача не про скорость или время).`,
explain2:`Пример: ${F('x²','x − 3')} = ${F(9,'x − 3')} → x² = 9 → x = ±3. Но x = 3 даёт ${F(9,0)} — такого не бывает. Проверка по ОДЗ спасла ответ: только −3.`};},false,true);
G(3,()=>{let e,r;do{e=nz(-7,7);r=nz(-7,7);}while(r===e);
const rhs=pf([-e*r,e+r]);ok(near(r*r/(r-e),((e+r)*r-e*r)/(r-e)),'ext');
return {type:'set',q:`Реши уравнение ${M(F('x²',xp(-e))+' = '+F(rhs,xp(-e)))}.`,ans:[r],ph:'корни через «;» или ∅',
hint:'Знаменатели одинаковые — приравняй числители. Потом проверь ОДЗ!',
explain:`ОДЗ: x ≠ ${N(e)}.<br>Знаменатели одинаковые → числители равны: x² = ${rhs} → ${pf([e*r,-(e+r),1])} = 0.<br>По Виету: x₁ + x₂ = ${N(e+r)}, x₁x₂ = ${N(e*r)} → x = ${N(e)} или x = ${N(r)}.<br>x = ${N(e)} обращает знаменатель в ноль — <b>посторонний</b>!<br>Ответ: <b>${N(r)}</b>.`,
explain2:`Подставь оба кандидата в <b>исходное</b> уравнение. x = ${N(r)}: внизу ${N(r-e)} ≠ 0, сверху ${N(r*r)} и ${N((e+r)*r-e*r)} — равны ✅. x = ${N(e)}: внизу ${N(e)} − ${pn(e)} = 0 — делить нельзя ❌.`,
short:`Получаем x = ${N(e)} или x = ${N(r)}, но x = ${N(e)} обнуляет знаменатель. Ответ: ${N(r)}.`};});
G(3,()=>{let a,b,k,s,r,c;do{a=R(1,7);b=R(1,7);k=R(1,6);s=pick([1,-1]);r=s*k;c=(a+b)*r+(a-b)*k;}while(c===0);
return {type:'set',q:`Реши уравнение ${M(F(a,xp(-k))+' + '+F(b,xp(k))+' = '+F(c,`x² − ${k*k}`))}.`,ans:[],ph:'корни через «;» или ∅',
hint:'Реши как обычно, а потом обязательно проверь ОДЗ.',
short:`Получается x = ${N(r)}, но он запрещён (x ≠ ±${k}). Корней нет.`,
explain:`ОДЗ: x ≠ ${k}, x ≠ −${k}.<br>Умножаем на (x − ${k})(x + ${k}): ${a}(x + ${k}) + ${b}(x − ${k}) = ${N(c)} → ${a+b}x = ${N(c-(a-b)*k)} → x = ${N(r)}.<br>Но x = ${N(r)} — <b>запрещённое</b> значение! Это посторонний корень.<br>Ответ: <b>корней нет</b> (введи ∅).`,
explain2:`Подставь x = ${N(r)} в исходное уравнение: в знаменателе ${s>0?`первой дроби ${k} − ${k}`:`второй дроби −${k} + ${k}`} = 0. Делить на ноль нельзя — значит, x = ${N(r)} не корень. А других кандидатов нет. Так бывает: честно решил, а корней нет.`};});
G(3,()=>{const a=nz(-6,6);const trap=Math.random()<0.55;let c;if(trap)c=2*a;else{do{c=nz(-9,12);}while(c===2*a||c===a);}
const root=c-a;const ans=trap?[]:[root];
return {type:'set',q:`Реши уравнение ${M(F(`x² − ${a*a}`,xp(-a))+' = '+N(c))}.`,ans,ph:'корни через «;» или ∅',
hint:'Сократи дробь, но запомни, какой x запрещён.',
short:trap?`x + ${pn(a)} = ${N(c)} → x = ${N(a)} — но он запрещён. Корней нет.`:`x ${a>0?'+':'−'} ${Math.abs(a)} = ${N(c)} → x = ${N(root)}.`,
explain:`ОДЗ: x ≠ ${N(a)}.<br>Сокращаем: ${F(`(${xp(-a)})(${xp(a)})`,xp(-a))} = ${xp(a)}.<br>Уравнение: ${xp(a)} = ${N(c)} → x = ${N(root)}.<br>${trap?`Но x = ${N(a)} запрещён! Это посторонний корень. Ответ: <b>корней нет</b> (∅).`:`${N(root)} ≠ ${N(a)} ✅. Ответ: <b>${N(root)}</b>.`}`,
explain2:trap?`Посмотри на дробь: при любом разрешённом x она равна x ${a>0?'+':'−'} ${Math.abs(a)}. Чтобы это было ${N(c)}, нужен x = ${N(a)} — единственный запрещённый x. Как дверь, к которой подходит только один ключ, а он сломан.`:`Проверка: при x = ${N(root)} числитель ${N(root*root-a*a)}, знаменатель ${N(root-a)}, дробь = ${N((root*root-a*a)/(root-a))} ✅.`};});
G(3,()=>{let a,rg,rb;for(;;){a=R(1,6);rb=pick([a,-a]);rg=nz(-8,8);if(rg===a||rg===-a)continue;const b=rg+rb+a;if(b!==0&&a*b-rg*rb!==0)break;}
const b=rg+rb+a,c=a*b-rg*rb;
ok(near(rg/(rg-a)-b/(rg+a),c/(rg*rg-a*a)),'L3c');
const r=ch(`только x = ${N(rg)}`,['оба числа',`только x = ${N(rb)}`,'ни одно']);
return {type:'choice',q:`Решая уравнение ${M(F('x',xp(-a))+' − '+F(b,xp(a))+' = '+F(c,`x² − ${a*a}`))}, Артём получил квадратное уравнение с корнями x = ${N(rg)} и x = ${N(rb)}. Что пойдёт в ответ?`,...r,
short:`x = ${N(rb)} обращает знаменатель в ноль — посторонний.`,
explain:`ОДЗ: x ≠ ${a}, x ≠ −${a}. Корень x = ${N(rb)} — запрещённый, значит посторонний.<br>x = ${N(rg)} разрешён ✅.<br>Ответ: <b>${N(rg)}</b>.`,
explain2:`Подставь x = ${N(rb)} в ${rb>0?`x − ${a}`:`x + ${a}`}: получится 0, а делить на ноль нельзя. А x = ${N(rg)} не обнуляет ни одного знаменателя — его оставляем.`};});

/* L4 — алгоритм, квадратные */
G(4,()=>{const right='ОДЗ → умножить на общий знаменатель → решить → вычеркнуть посторонние корни';
const r=ch(right,['умножить на общий знаменатель → решить → записать все корни в ответ','решить → найти ОДЗ → умножить на знаменатель → ответ','сократить все дроби → решить → ответ']);
return {type:'choice',q:'Какой порядок решения дробно-рационального уравнения правильный?',...r,
short:'Сначала ОДЗ, в конце — отсев посторонних.',
explain:`Правильно: <b>${right}</b>.<br>Главное, чего не хватает в других вариантах, — <b>проверки корней по ОДЗ</b>. Без неё в ответ попадут посторонние корни.`,
explain2:'Запомни как «бутерброд»: сверху ОДЗ, внутри — обычное решение, снизу — сверка с ОДЗ. Без верхнего и нижнего хлеба бутерброд разваливается.'};},false,true);
G(4,()=>{let r1,r2;do{r1=nz(-9,9);r2=nz(-9,9);}while(r1===r2||r1+r2===0);
const m=r1+r2,q=r1*r2;ok(near(r1+q/r1,m)&&near(r2+q/r2,m),'x+q/x');
const lhs=`x ${q>0?'+':'−'} ${F(Math.abs(q),'x')}`;
return {type:'set',q:`Реши уравнение ${M(lhs+' = '+N(m))}.`,ans:[r1,r2],ph:'корни через «;»',
hint:'Умножь обе части на x (x ≠ 0).',
short:`x² − ${pn(m)}x + ${pn(q)} = 0 → x = ${N(r1)}; ${N(r2)}.`,
explain:`ОДЗ: x ≠ 0.<br>Умножаем на x: x² ${q>0?'+':'−'} ${Math.abs(q)} = ${cx(m)}x → ${pf([q,-m,1])} = 0.<br>По Виету: сумма корней ${N(m)}, произведение ${N(q)} → x = ${N(r1)} и x = ${N(r2)}.<br>Оба ≠ 0 ✅. Ответ: <b>${N(r1)}; ${N(r2)}</b>.`,
explain2:`Проверка: x = ${N(r1)}: ${N(r1)} + ${F(N(q),N(r1))} = ${N(r1)} + ${pn(q/r1)} = ${N(m)} ✅. x = ${N(r2)}: ${N(r2)} + ${pn(q/r2)} = ${N(m)} ✅. Если Виет не подбирается — решай через дискриминант: D = ${N(m*m-4*q)}.`};});
const L4b=(withExt)=>()=>{let a,r1,r2,b,c;for(let t=0;;t++){a=R(1,6);r1=nz(-8,8);r2=withExt?pick([a,-a]):nz(-8,8);if(r1===r2||r1===a||r1===-a)continue;if(!withExt&&(r2===a||r2===-a))continue;b=r1+r2+a;c=a*b-r1*r2;if(b!==0&&c!==0)break;}
const good=withExt?[r1]:[r1,r2];good.forEach(x=>ok(near(x/(x-a)-b/(x+a),c/(x*x-a*a)),'L4b'));
const sq=pf([a*b-c,a-b,1]);
return {type:'set',q:`Реши уравнение ${M(F('x',xp(-a))+' − '+F(b,xp(a))+' = '+F(c,`x² − ${a*a}`))}.`,ans:good,ph:'корни через «;» или ∅',
hint:`Общий знаменатель (x − ${a})(x + ${a}). Не забудь, что минус перед второй дробью относится ко всему.`,
short:`${sq} = 0 → x = ${N(r1)}; ${N(r2)}${withExt?`, но ${N(r2)} посторонний`:''}.`,
explain:`ОДЗ: x ≠ ±${a}.<br>Умножаем на (x − ${a})(x + ${a}):<br>x(x + ${a}) − ${b<0?`(${N(b)})`:b}(x − ${a}) = ${N(c)}<br>x² + ${cx(a)}x ${b>0?'−':'+'} ${cx(Math.abs(b))}x ${b*a>0?'+':'−'} ${Math.abs(a*b)} − ${pn(c)} = 0 → <b>${sq} = 0</b>.<br>Корни (Виет: сумма ${N(r1+r2)}, произведение ${N(r1*r2)}): x = ${N(r1)}, x = ${N(r2)}.<br>${withExt?`x = ${N(r2)} запрещён — <b>посторонний</b>! Ответ: <b>${N(r1)}</b>.`:`Оба разрешены ✅. Ответ: <b>${N(r1)}; ${N(r2)}</b>.`}`,
explain2:`Проверь по ОДЗ каждый корень: ${[r1,r2].map(x=>`x = ${N(x)} — ${(x===a||x===-a)?'обнуляет знаменатель ❌':'знаменатели ≠ 0 ✅'}`).join('; ')}. Если сомневаешься в квадратном уравнении — D = ${N((a-b)*(a-b)-4*(a*b-c))}, √D = ${N(Math.abs(r1-r2))}.`};};
G(4,L4b(false));G(4,L4b(true));
G(4,()=>{let a,b,c,rr;for(;;){a=nz(-9,12);b=nz(-9,12);c=nz(-8,8);const qd=quad(1,-(c+a+b),a*c);if(qd.D<=0)continue;rr=qd.r;if(!rr.every(isInt))continue;rr=rr.map(Math.round);if(rr.some(x=>x===0||x===c))continue;break;}
rr.forEach(x=>ok(near(a/x+b/(x-c),1),'a/x+b/(x-c)'));
const t1=a>0?F(a,'x'):'−'+F(-a,'x'),t2=F(Math.abs(b),xp(-c));const sq=pf([a*c,-(c+a+b),1]);
return {type:'set',q:`Реши уравнение ${M(t1+(b>0?' + ':' − ')+t2+' = 1')}.`,ans:rr,ph:'корни через «;»',
hint:`Общий знаменатель x(${xp(-c)}).`,
short:`${sq} = 0 → x = ${rr.map(N).join('; ')}.`,
explain:`ОДЗ: x ≠ 0, x ≠ ${N(c)}.<br>Умножаем на x(${xp(-c)}): ${N(a)}(${xp(-c)}) ${b>0?'+':'−'} ${cx(Math.abs(b))}x = x(${xp(-c)}).<br>${pf([-a*c,a])} ${b>0?'+':'−'} ${Math.abs(b)}x = ${pf([0,-c,1])} → <b>${sq} = 0</b>.<br>D = ${N((c+a+b)**2-4*a*c)}, корни x = ${rr.map(N).join(' и x = ')}.<br>Оба не равны 0 и ${N(c)} ✅. Ответ: <b>${rr.map(N).join('; ')}</b>.`,
explain2:`Проверка: ${rr.map(x=>`x = ${N(x)}: ${F(N(a),pn(x))} + ${F(N(b),pn(x-c))} = ${qh(a,x)} ${b*(x-c)<0?'−':'+'} ${qh(Math.abs(b),Math.abs(x-c))} = 1 ✅`).join('<br>')}`};});

/* L5 — замена */
G(5,()=>{const r=ch('обозначить повторяющееся выражение новой буквой, решить и вернуться к x',['подставить вместо x любое удобное число','заменить все дроби десятичными','поменять местами левую и правую части']);
return {type:'choice',q:'Что значит «сделать замену переменной»?',...r,
short:'Повторяющийся «кирпичик» = t, решаем для t, потом возвращаемся к x.',
explain:`Замена: видишь, что одно и то же выражение повторяется, — обозначаешь его <b>t</b>. Уравнение для t проще. Найдя t, <b>обязательно возвращаешься</b> к x: решаешь «выражение = t».`,
explain2:`Как в чате: вместо «Артём Владимирович Иванов» пишешь «Тёма». Переписка короче, но в конце всё равно имеешь в виду того же человека. t — короткое имя для длинного выражения.`};},false,true);
G(5,()=>{const n=R(2,6);const nf=F(n*n+1,n);ok(near(n+1/n,(n*n+1)/n),'x+1/x');
return {type:'set',q:`Реши уравнение ${M('x + '+F(1,'x')+' = '+nf)}. Дробный корень вводи как дробь: 1/${n}.`,ans:[n,1/n],ansText:`${n}; ${F(1,n)}`,ph:`например: 2; 1/2`,
hint:`${nf} = ${n} + ${F(1,n)}. Видишь похожесть?`,
short:`${nf} = ${n} + ${F(1,n)}, поэтому x = ${n} или x = ${F(1,n)}.`,
explain:`ОДЗ: x ≠ 0. Умножаем на ${n}x: ${n}x² + ${n} = ${n*n+1}x → ${n}x² − ${n*n+1}x + ${n} = 0.<br>D = ${(n*n+1)**2} − ${4*n*n} = ${(n*n-1)**2}, √D = ${n*n-1}.<br>x = ${F(`${n*n+1} ± ${n*n-1}`,2*n)} → x = ${n} или x = ${F(1,n)}.<br>Ответ: <b>${n}; ${F(1,n)}</b>.`,
explain2:`Хитрый способ без вычислений: правая часть ${nf} = ${n} + ${F(1,n)} — это «число плюс обратное». Уравнение x + ${F(1,'x')} = ${n} + ${F(1,n)} подходит при x = ${n}, а ещё при x = ${F(1,n)} (тогда ${F(1,'x')} = ${n}). А квадратное уравнение больше двух корней не имеет.`};});
G(5,()=>{const a=R(3,9);const ans=a*a-2;
return {type:'num',q:`Известно, что ${M('x + '+F(1,'x')+' = '+a)}. Найди ${M('x² + '+F(1,'x²'))}.`,ans,
hint:`Возведи обе части в квадрат.`,
short:`(x + 1/x)² = x² + 2 + 1/x² → ${a*a} − 2 = ${ans}.`,
explain:`Возводим в квадрат: (x + ${F(1,'x')})² = x² + 2·x·${F(1,'x')} + ${F(1,'x²')} = x² + 2 + ${F(1,'x²')}.<br>Значит, x² + ${F(1,'x²')} = ${a}² − 2 = ${a*a} − 2 = <b>${ans}</b>.<div class="box err"><b>Ловушка</b>Ответ ${a*a}: забыли, что x·${F(1,'x')} = 1, и удвоенное произведение даёт +2.</div>`,
explain2:`Само x искать не нужно (оно некрасивое). Формула квадрата суммы: (p + q)² = p² + 2pq + q². Здесь p = x, q = ${F(1,'x')}, pq = 1. Поэтому «лишние» 2 надо вычесть: ${a*a} − 2 = ${ans}.`};});
G(5,()=>{let p,q;do{p=nz(-7,7);q=nz(-7,7);}while(p===q||p+q===0||Math.abs(p*q)>40);
const P=p*q,S=p+q;[p,q].forEach(x=>ok(near(P/(x*x)-S/x+1,0),'1/x'));
const t1=(P<0?'−':'')+F(Math.abs(P),'x²'),t2=(S>0?' − ':' + ')+F(Math.abs(S),'x');
return {type:'set',q:`Реши уравнение ${M(t1+t2+' + 1 = 0')}.`,ans:[p,q],ph:'корни через «;»',
hint:`Замена t = ${F(1,'x')}. Тогда ${F(1,'x²')} = t².`,
short:`${N(P)}t² − ${pn(S)}t + 1 = 0 → t = ${qh(1,p)}, ${qh(1,q)} → x = ${N(p)}; ${N(q)}.`,
explain:`ОДЗ: x ≠ 0. Пусть t = ${F(1,'x')}, тогда ${F(1,'x²')} = t²:<br>${N(P)}t² ${S>0?'−':'+'} ${cx(Math.abs(S))}t + 1 = 0.<br>D = ${S*S} ${P<0?'+':'−'} ${Math.abs(4*P)} = ${N(S*S-4*P)}, √D = ${N(Math.abs(p-q))}. t = ${F(`${N(S)} ± ${Math.abs(p-q)}`,N(2*P))} → t = ${qh(1,p)} или t = ${qh(1,q)}.<br>Возвращаемся: ${F(1,'x')} = t → x = ${F(1,'t')} → x = ${N(p)} или x = ${N(q)}.<br>Ответ: <b>${N(p)}; ${N(q)}</b>.`,
explain2:`Другой путь — сразу умножить на x²: ${N(P)} ${S>0?'−':'+'} ${cx(Math.abs(S))}x + x² = 0 → x² ${S>0?'−':'+'} ${cx(Math.abs(S))}x ${P>0?'+':'−'} ${Math.abs(P)} = 0. По Виету: сумма ${N(S)}, произведение ${N(P)} → ${N(p)} и ${N(q)}. Тот же ответ!`};});
G(5,()=>{const n=pick([2,2,3]);let k=n===3?2*R(1,4):nz(-6,6);if(n===3&&Math.random()<0.4)k=-k;
const x1=n*k/(n-1),x2=-k/(n-1);[x1,x2].forEach(x=>ok(near(x/(x-k)+(x-k)/x,n+1/n),'sub'));
const rhs=F(n*n+1,n);
return {type:'set',q:`Реши уравнение ${M(F('x',xp(-k))+' + '+F(xp(-k),'x')+' = '+rhs)}.`,ans:[x1,x2],ph:'корни через «;»',
hint:`Вторая дробь — перевёрнутая первая. Пусть t = ${F('x',xp(-k))}.`,
short:`t + 1/t = ${rhs} → t = ${n} или ${F(1,n)} → x = ${N(x1)}; ${N(x2)}.`,
explain:`ОДЗ: x ≠ 0, x ≠ ${N(k)}. Пусть t = ${F('x',xp(-k))}, тогда вторая дробь = ${F(1,'t')}.<br>t + ${F(1,'t')} = ${rhs} → ${n}t² − ${n*n+1}t + ${n} = 0 → t = ${n} или t = ${F(1,n)}.<br>Возвращаемся к x:<br>• ${F('x',xp(-k))} = ${n} → x = ${n}x − ${pn(n*k)} → x = ${N(x1)};<br>• ${F('x',xp(-k))} = ${F(1,n)} → ${n}x = x − ${pn(k)} → x = ${N(x2)}.<br>Ответ: <b>${N(x1)}; ${N(x2)}</b>.`,
explain2:`Проверка для x = ${N(x1)}: ${F(N(x1),N(x1-k))} = ${N(x1/(x1-k))}, обратная = ${qh(1,n)}, сумма ${rhs} ✅. Главное — не остановиться на t = ${n} и t = ${F(1,n)}: это ещё не ответ!`};});
G(5,()=>{const K=pick([6,8,10,12,18,20]);const pairs=[];for(let d=1;d*d<K;d++)if(K%d===0){pairs.push([d,K/d]);pairs.push([-d,-K/d]);}
let A,B,t1,t2;do{[A,B]=sample(pairs,2);t1=A[0]+A[1];t2=B[0]+B[1];}while(t1===t2||t1+t2===0);
const roots=[...A,...B];ok(uniq(roots),'uniq');roots.forEach(x=>{const t=x+K/x;ok(near(t*t-(t1+t2)*t+t1*t2,0),'K');});
const S=t1+t2,P=t1*t2;const brick=`(x + ${F(K,'x')})`;
return {type:'set',q:`Реши уравнение ${M(`${brick}² ${S>0?'−':'+'} ${cx(Math.abs(S))}${brick} ${P>0?'+':'−'} ${Math.abs(P)} = 0`)}.`,ans:roots,ph:'все корни через «;»',
hint:`Замена t = x + ${F(K,'x')}.`,
short:`t = ${N(t1)} или t = ${N(t2)}; из каждого — по два x: ${roots.map(N).join('; ')}.`,
explain:`ОДЗ: x ≠ 0. Пусть t = x + ${F(K,'x')}: t² ${S>0?'−':'+'} ${cx(Math.abs(S))}t ${P>0?'+':'−'} ${Math.abs(P)} = 0 → t = ${N(t1)} или t = ${N(t2)} (Виет).<br>Возвращаемся:<br>• x + ${F(K,'x')} = ${N(t1)} → x² ${t1>0?'−':'+'} ${Math.abs(t1)}x + ${K} = 0 → x = ${N(A[0])}; ${N(A[1])};<br>• x + ${F(K,'x')} = ${N(t2)} → x² ${t2>0?'−':'+'} ${Math.abs(t2)}x + ${K} = 0 → x = ${N(B[0])}; ${N(B[1])}.<br>Ответ: <b>${roots.map(N).join('; ')}</b> — целых четыре корня!`,
explain2:`Без замены пришлось бы раскрывать скобки и получить уравнение 4-й степени. А так — два маленьких квадратных. Проверь любой корень, например x = ${N(A[0])}: ${N(A[0])} + ${F(K,N(A[0]))} = ${N(t1)}, и ${N(t1)}² ${S>0?'−':'+'} ${Math.abs(S)}·${pn(t1)} ${P>0?'+':'−'} ${Math.abs(P)} = 0 ✅.`};});

/* L6 — река */
function riverData(){for(;;){const v=R(6,24),u=R(1,5);if(v<=u+1)continue;const L=v*v-u*u;const l=(v+u)*(v-u)/gcd(v+u,v-u);const k=R(1,4);const S=l*k;if(S<12||S>150)continue;const T=S/(v+u)+S/(v-u);if(!isInt(T)||T>20)continue;
 const D=4*S*S+4*T*T*u*u;const s=Math.sqrt(D);if(!isInt(s))continue;return {v,u,S,T,D,s:Math.round(s),t1:S/(v+u),t2:S/(v-u)};}}
const VEH=[['Катер','прошёл'],['Моторная лодка','прошла'],['Каякер на сплаве','прошёл'],['Дрон-катамаран','прошёл']];
G(6,()=>{const r=ch('по течению v + u, против течения v − u',['по течению v − u, против течения v + u','по течению v·u, против v : u','и по течению, и против — просто v']);
return {type:'choice',q:'Собственная скорость лодки v, скорость течения u. Какое правило верное?',...r,
short:'Течение помогает (+) по течению и мешает (−) против.',
explain:`По течению вода «несёт» лодку вперёд — скорости <b>складываются</b>: v + u. Против — вода тормозит: <b>v − u</b>. Плот без мотора плывёт со скоростью течения u.`,
explain2:`Траволатор в аэропорту: идёшь 5 км/ч, дорожка едет 3 км/ч. По ходу дорожки — 5 + 3 = 8 км/ч, против — 5 − 3 = 2 км/ч. С рекой то же самое.`};},false,true);
G(6,()=>{const d=riverData();const [veh,verb]=pick(VEH);
return {type:'num',q:`${veh} ${verb} ${d.S} км по течению реки и ${d.S} км обратно, затратив на весь путь ${d.T} ч. Скорость течения ${d.u} км/ч. Найди собственную скорость (км/ч).`,ans:d.v,
hint:`Время = путь : скорость. ${F(d.S,`x + ${d.u}`)} + ${F(d.S,`x − ${d.u}`)} = ${d.T}.`,
short:`${d.S} : ${d.v+d.u} + ${d.S} : ${d.v-d.u} = ${N(d.t1)} + ${N(d.t2)} = ${d.T} ✅ → ${d.v} км/ч.`,
explain:`Пусть x — собственная скорость. По течению x + ${d.u}, против x − ${d.u}.<br>${F(d.S,`x + ${d.u}`)} + ${F(d.S,`x − ${d.u}`)} = ${d.T}.<br>Умножаем на (x + ${d.u})(x − ${d.u}): ${d.S}(x − ${d.u}) + ${d.S}(x + ${d.u}) = ${d.T}(x² − ${d.u*d.u}).<br>${2*d.S}x = ${d.T}x² − ${d.T*d.u*d.u} → ${d.T}x² − ${2*d.S}x − ${d.T*d.u*d.u} = 0.<br>D = ${d.D}, √D = ${d.s}. x = ${F(`${2*d.S} ± ${d.s}`,2*d.T)} → x = ${d.v} или x &lt; 0.<br>Скорость положительная → <b>${d.v} км/ч</b>.`,
explain2:`Проверка: по течению ${d.v} + ${d.u} = ${d.v+d.u} км/ч, время ${d.S} : ${d.v+d.u} = ${N(d.t1)} ч. Против: ${d.v} − ${d.u} = ${d.v-d.u} км/ч, время ${d.S} : ${d.v-d.u} = ${N(d.t2)} ч. Всего ${N(d.t1)} + ${N(d.t2)} = ${d.T} ч ✅. Отрицательный корень — математически корень, но скорость лодки не может быть отрицательной.`};});
G(6,()=>{const d=riverData();
return {type:'num',q:`Моторная лодка с собственной скоростью ${d.v} км/ч прошла ${d.S} км по течению и вернулась обратно. Весь путь занял ${d.T} ч. Найди скорость течения (км/ч).`,ans:d.u,
hint:`${F(d.S,`${d.v} + x`)} + ${F(d.S,`${d.v} − x`)} = ${d.T}.`,
short:`${d.S} : ${d.v+d.u} + ${d.S} : ${d.v-d.u} = ${d.T} → течение ${d.u} км/ч.`,
explain:`Пусть x — скорость течения. ${F(d.S,`${d.v} + x`)} + ${F(d.S,`${d.v} − x`)} = ${d.T}.<br>Умножаем на (${d.v} + x)(${d.v} − x) = ${d.v*d.v} − x²:<br>${d.S}(${d.v} − x) + ${d.S}(${d.v} + x) = ${d.T}(${d.v*d.v} − x²) → ${2*d.S*d.v} = ${d.T*d.v*d.v} − ${d.T}x².<br>${d.T}x² = ${d.T*d.v*d.v-2*d.S*d.v} → x² = ${d.u*d.u} → x = ${d.u} (x = −${d.u} не подходит).<br>Ответ: <b>${d.u} км/ч</b>.`,
explain2:`Заметь: слагаемые с x в числителе сократились (−${d.S}x + ${d.S}x = 0) — так бывает всегда, когда путь туда и обратно одинаковый. Проверка: ${N(d.t1)} + ${N(d.t2)} = ${d.T} ✅.`};});
G(6,()=>{const S=pick([20,24,30,36,48]),u=R(1,4),T=R(3,8);const right=`${F(S,`x + ${u}`)} + ${F(S,`x − ${u}`)} = ${T}`;
const r=ch(right,[`${F(S,`x − ${u}`)} − ${F(S,`x + ${u}`)} = ${T}`,`${S}(x + ${u}) + ${S}(x − ${u}) = ${T}`,`${F(2*S,'x')} = ${T}`]);
return {type:'choice',q:`Лодка прошла ${S} км по течению и столько же обратно за ${T} ч. Скорость течения ${u} км/ч, x — собственная скорость. Какое уравнение верно?`,opts:r.opts.map(M),ans:r.ans,
short:'Время туда + время обратно = всё время.',
explain:`Время = путь : скорость. Туда: ${F(S,`x + ${u}`)} ч, обратно: ${F(S,`x − ${u}`)} ч. Вместе — ${T} ч: ${M(right)}.<br>• ${S}(x + ${u}) — это путь × скорость, такой величины в задаче нет.<br>• ${F(2*S,'x')} — так было бы в стоячей воде, без течения.<br>• Разность времён была бы нужна, если бы сказали «обратно плыла на ${T} ч дольше».`,
explain2:'Проверь единицы: км : (км/ч) = ч. Только у дробей «путь / скорость» получаются часы — их и складываем.'};});

/* L7 — работа */
const PAIRS=[];for(let a=2;a<=40;a++)for(let b=a+1;b<=60;b++){const t=a*b/(a+b);if(isInt(t*2)&&t>=1)PAIRS.push([a,b,t]);}
const JOBS=[['Два принтера печатают тираж листовок','ч'],['Две трубы наполняют бассейн','ч'],['Два робота-пылесоса убирают торговый центр','ч'],['Два сервера обрабатывают видео для YouTube','мин']];
G(7,()=>{const r=ch(`за единицу времени делается ${F(1,'t')} часть работы; вместе производительности складываются`,['вместе нужно t₁ + t₂ времени','вместе нужно (t₁ + t₂) : 2 времени','производительность равна t']);
return {type:'choice',q:'Работу делают за t часов. Какое правило про совместную работу верное?',...r,
short:'Производительность = 1/t, вместе — сумма производительностей.',
explain:`Всю работу принимаем за 1. За t часов — вся работа, значит, за 1 час — <b>${F(1,'t')}</b> часть. Если работают двое, за час они делают ${F(1,'t₁')} + ${F(1,'t₂')}.<br>Складывать <b>времена</b> нельзя: вдвоём работа идёт быстрее, а не медленнее!`,
explain2:'Красим забор: ты один — за 4 ч, друг один — за 4 ч. Вместе вы красите в 2 раза быстрее — за 2 ч, а не за 8 и не за 4. За час каждый красит 1/4, вместе 1/4 + 1/4 = 1/2 забора.'};},false,true);
G(7,()=>{const [a,b,t]=pick(PAIRS.filter(p=>p[1]<=30));const [job,unit]=pick(JOBS);ok(near(1/a+1/b,1/t),'pair');
return {type:'num',q:`${job}: первый справляется за ${a} ${unit}, второй — за ${b} ${unit}. За сколько ${unit} они справятся, работая вместе?`,ans:t,
hint:'За единицу времени первый делает 1/'+a+' работы, второй 1/'+b+'.',
short:`${F(1,a)} + ${F(1,b)} = ${qh(a+b,a*b)} → ${N(t)} ${unit}.`,
explain:`Вся работа = 1.<br>За 1 ${unit}: первый — ${F(1,a)}, второй — ${F(1,b)}. Вместе: ${F(1,a)} + ${F(1,b)} = ${F(b+a,a*b)} = ${qh(a+b,a*b)} работы.<br>Вся работа: 1 : ${qh(a+b,a*b)} = <b>${N(t)} ${unit}</b>.<div class="box err"><b>Ловушка</b>(${a} + ${b}) : 2 = ${N((a+b)/2)} — неверно. Вместе быстрее, чем самый быстрый в одиночку: ответ меньше ${a}.</div>`,
explain2:`Посчитай «в штуках». Пусть работа — ${a*b/gcd(a,b)} листов/литров/… Первый за 1 ${unit} делает ${a*b/gcd(a,b)/a}, второй — ${a*b/gcd(a,b)/b}, вместе ${(a*b/gcd(a,b))*(1/a+1/b)}. Всё сделают за ${a*b/gcd(a,b)} : ${(a*b/gcd(a,b))*(1/a+1/b)} = ${N(t)} ${unit}.`};});
const WORK2=[];for(let x=2;x<=30;x++)for(let d=1;d<=20;d++){const t=x*(x+d)/(2*x+d);if(isInt(t)&&isInt(t*d/x))WORK2.push([x,d,Math.round(t)]);}
G(7,()=>{const [x,d,t]=pick(WORK2);ok(near(1/x+1/(x+d),1/t),'w2');const B=d-2*t,C=-t*d;const s=x+t*d/x;
return {type:'num',q:`Два бота вместе собирают ферму в Minecraft за ${t} мин. Первому боту одному нужно на ${d} мин больше, чем второму. За сколько минут справится <b>второй</b> бот один?`,ans:x,
hint:`Пусть второй — x мин, тогда первый — x + ${d}. ${F(1,'x')} + ${F(1,`x + ${d}`)} = ${F(1,t)}.`,
short:`${F(1,x)} + ${F(1,x+d)} = ${F(1,t)} ✅ → ${x} мин.`,
explain:`Пусть второй — x мин, первый — (x + ${d}) мин. За минуту вместе: ${F(1,'x')} + ${F(1,`x + ${d}`)} = ${F(1,t)}.<br>Умножаем на ${t}x(x + ${d}): ${t}(x + ${d}) + ${t}x = x(x + ${d}).<br>${2*t}x + ${t*d} = x² + ${d}x → ${pf([C,B,1])} = 0.<br>D = ${B*B-4*C}, √D = ${N(s)}. x = ${x} или x = ${N(-t*d/x)} (время не бывает отрицательным).<br>Ответ: <b>${x} мин</b>, а первому нужно ${x+d} мин.`,
explain2:`Проверка: за минуту второй делает ${F(1,x)}, первый ${F(1,x+d)}. Вместе ${F(1,x)} + ${F(1,x+d)} = ${qh(2*x+d,x*(x+d))} = ${F(1,t)} — ровно столько, чтобы закончить за ${t} мин ✅.`};});
G(7,()=>{const [a,b,t]=pick(PAIRS.filter(p=>isInt(p[2])&&p[1]<=60));const [job,unit]=pick(JOBS);ok(near(1/t-1/a,1/b),'w3');
return {type:'num',q:`${job}. Вместе они справляются за ${N(t)} ${unit}, а первый в одиночку — за ${a} ${unit}. За сколько ${unit} справится второй в одиночку?`,ans:b,
hint:`Производительность второго = ${F(1,N(t))} − ${F(1,a)}.`,
short:`${F(1,N(t))} − ${F(1,a)} = ${F(1,b)} → ${b} ${unit}.`,
explain:`Вместе за 1 ${unit}: ${F(1,N(t))} работы. Первый: ${F(1,a)}. Значит, второй: ${F(1,N(t))} − ${F(1,a)} = ${qh(a-t,a*t)}.<br>Второй сделает всю работу за 1 : ${qh(a-t,a*t)} = <b>${b} ${unit}</b>.`,
explain2:`Уравнением: ${F(1,a)} + ${F(1,'x')} = ${F(1,N(t))}. Умножим на ${a*t}x: ${t}x + ${a*t} = ${a}x → ${cx(a-t)}x = ${a*t} → x = ${b}. Разумно: второй медленнее первого, ведь вместе (${N(t)}) лишь чуть быстрее первого (${a}).`};});

/* L8 — ★ */
G(8,()=>{const r=ch(`x + ${F(1,'x')} ≥ 2, равенство только при x = 1`,[`x + ${F(1,'x')} ≤ 2, равенство при x = 1`,`x + ${F(1,'x')} ≥ 1, равенство при x = 1`,`x + ${F(1,'x')} ≥ 2, равенство при x = 2`]);
return {type:'choice',q:`Какое утверждение верно для любого x > 0?`,opts:r.opts.map(M),ans:r.ans,
short:'x + 1/x − 2 = (x − 1)²/x ≥ 0.',
explain:`x + ${F(1,'x')} − 2 = ${F('x² − 2x + 1','x')} = ${F('(x − 1)²','x')}. Квадрат ≥ 0, а x > 0, значит, вся дробь ≥ 0. Отсюда <b>x + ${F(1,'x')} ≥ 2</b>, и 0 получается только при x = 1.`,
explain2:`Проверь числами: x = 2 → 2,5; x = ${F(1,2)} → 2,5; x = 10 → 10,1; x = 1 → ровно 2. Меньше двух никогда не получается.`};},true,true);
G(8,()=>{const m=R(2,9);const roots=[m,-m-3];
roots.forEach(x=>ok(near(1/(x*(x+1))+1/((x+1)*(x+2))+1/((x+2)*(x+3)),3/(m*(m+3))),'tele'));
const rhs=qh(3,m*(m+3));
return {type:'set',q:`Реши уравнение ${M(F(1,'x(x + 1)')+' + '+F(1,'(x + 1)(x + 2)')+' + '+F(1,'(x + 2)(x + 3)')+' = '+rhs)}.`,ans:roots,ph:'корни через «;»',
hint:`${F(1,'n(n + 1)')} = ${F(1,'n')} − ${F(1,'n + 1')}. Распиши каждую дробь так.`,
short:`Левая часть = ${F(1,'x')} − ${F(1,'x + 3')} = ${F(3,'x(x + 3)')} → x(x + 3) = ${m*(m+3)} → x = ${m}; ${-m-3}.`,
explain:`Телескоп: ${F(1,'x(x + 1)')} = ${F(1,'x')} − ${F(1,'x + 1')}, ${F(1,'(x + 1)(x + 2)')} = ${F(1,'x + 1')} − ${F(1,'x + 2')}, ${F(1,'(x + 2)(x + 3)')} = ${F(1,'x + 2')} − ${F(1,'x + 3')}.<br>Складываем — серединки сокращаются: ${F(1,'x')} − ${F(1,'x + 3')} = ${F(3,'x(x + 3)')}.<br>${F(3,'x(x + 3)')} = ${rhs} → x(x + 3) = ${m*(m+3)} → x² + 3x − ${m*(m+3)} = 0 → x = ${m} или x = ${-m-3}.<br>ОДЗ: x ≠ 0, −1, −2, −3 — оба корня подходят. Ответ: <b>${m}; ${-m-3}</b>.`,
explain2:`Почему ${F(1,'n(n + 1)')} = ${F(1,'n')} − ${F(1,'n + 1')}: приведи правую часть к общему знаменателю — ${F('(n + 1) − n','n(n + 1)')} = ${F(1,'n(n + 1)')}. Проверка x = ${m}: ${F(1,m*(m+1))} + ${F(1,(m+1)*(m+2))} + ${F(1,(m+2)*(m+3))} = ${rhs} ✅. Не забудь отрицательный корень ${-m-3}!`};},true);
G(8,()=>{const a=R(2,6);const ans=a**3-3*a;const x=(a+Math.sqrt(a*a-4))/2;ok(near(x**3+1/x**3,ans),'cube');
return {type:'num',q:`Известно, что ${M('x + '+F(1,'x')+' = '+a)}. Найди ${M('x³ + '+F(1,'x³'))}.`,ans,
hint:`Возведи x + ${F(1,'x')} в куб: (p + q)³ = p³ + q³ + 3pq(p + q).`,
short:`${a}³ − 3·${a} = ${ans}.`,
explain:`(x + ${F(1,'x')})³ = x³ + ${F(1,'x³')} + 3·x·${F(1,'x')}·(x + ${F(1,'x')}) = x³ + ${F(1,'x³')} + 3·${a}.<br>Значит, x³ + ${F(1,'x³')} = ${a}³ − 3·${a} = ${a**3} − ${3*a} = <b>${ans}</b>.`,
explain2:`Другой путь: x² + ${F(1,'x²')} = ${a}² − 2 = ${a*a-2}. Перемножим: (x + ${F(1,'x')})(x² + ${F(1,'x²')}) = x³ + ${F(1,'x³')} + x + ${F(1,'x')}. То есть ${a}·${a*a-2} = (x³ + ${F(1,'x³')}) + ${a} → x³ + ${F(1,'x³')} = ${a*(a*a-2)} − ${a} = ${ans} ✅.`};},true);
const RAFT=[];for(let a=2;a<=10;a++)for(let b=a+1;b<=15;b++){const t=2*a*b/(b-a);if(isInt(t)&&t<=60)RAFT.push([a,b,t]);}
G(8,()=>{const [a,b,t]=pick(RAFT);const S=a*b*2;const v=(S/a+S/b)/2,u=(S/a-S/b)/2;ok(near(S/u,t),'raft');
return {type:'num',q:`Катер плывёт из города A в город B по течению ${a} ч, а обратно — ${b} ч. Сколько часов будет плыть из A в B плот?`,ans:t,
hint:'Обозначь путь S. Скорость по течению S/'+a+', против — S/'+b+'. Скорость течения — полуразность.',
short:`u = (S/${a} − S/${b}) : 2 = S/${t} → ${t} ч.`,
explain:`Пусть расстояние S. Тогда v + u = ${F('S',a)}, v − u = ${F('S',b)}.<br>Вычитаем: 2u = ${F('S',a)} − ${F('S',b)} = ${F(`${b-a===1?'':b-a}S`,a*b)} → u = ${F('S',t)}.<br>Плот плывёт со скоростью течения: время = S : ${F('S',t)} = <b>${t} ч</b>.`,
explain2:`Возьми удобное расстояние, например S = ${S} км. По течению: ${S} : ${a} = ${S/a} км/ч, против: ${S} : ${b} = ${S/b} км/ч. Течение = (${S/a} − ${S/b}) : 2 = ${N(u)} км/ч. Плот: ${S} : ${N(u)} = ${t} ч ✅. Ответ не зависит от S!`};},true);
const TRI=[];for(let a=2;a<=20;a++)for(let b=a+1;b<=30;b++)for(let c=b+1;c<=40;c++){const s=1/a+1/b+1/c;const p=[1/a-1/b+1/c,1/a+1/b-1/c,-1/a+1/b+1/c];if(p.some(v=>v<=1e-9))continue;const all=2/s;let den=0;for(let d=1;d<=6;d++)if(isInt(all*d)){den=d;break;}if(den)TRI.push([a,b,c,all,den]);}
G(8,()=>{const [p,q,r,all,den]=pick(TRI);const L=shuffle([p,q,r]);const ab=L[0],bc=L[1],ac=L[2];const ans=2/(1/ab+1/bc+1/ac);ok(near(ans,all),'tri');
const x=2/(1/ab-1/bc+1/ac),y=2/(1/ab+1/bc-1/ac),z=2/(-1/ab+1/bc+1/ac);ok(near(1/x+1/y,1/ab)&&near(1/y+1/z,1/bc)&&near(1/x+1/z,1/ac),'tri2');
const at=qh(Math.round(ans*den),den);const S=bc*ac+ab*ac+ab*bc,P=ab*bc*ac;
return {type:'num',q:`Бассейн наполняют три трубы. Первая и вторая вместе наполняют его за ${ab} ч, вторая и третья — за ${bc} ч, первая и третья — за ${ac} ч. За сколько часов наполнят бассейн все три трубы вместе? (Можно ответить дробью.)`,ans,ansText:at+' ч',
hint:'Сложи все три равенства про производительности: каждая труба войдёт дважды.',
short:`2(p₁ + p₂ + p₃) = ${F(1,ab)} + ${F(1,bc)} + ${F(1,ac)} → вместе ${at} ч.`,
explain:`Пусть p₁, p₂, p₃ — производительности (часть бассейна в час).<br>p₁ + p₂ = ${F(1,ab)}, p₂ + p₃ = ${F(1,bc)}, p₁ + p₃ = ${F(1,ac)}.<br>Складываем: 2(p₁ + p₂ + p₃) = ${F(1,ab)} + ${F(1,bc)} + ${F(1,ac)} = ${qh(S,P)}.<br>p₁ + p₂ + p₃ = ${qh(S,2*P)}.<br>Время: 1 : ${qh(S,2*P)} = <b>${at} ч</b>.<div class="box err"><b>Ловушка</b>Забыть разделить на 2: каждая труба в сумме посчитана дважды.</div>`,
explain2:`Каждую трубу по отдельности искать не нужно (хотя можно: первая — ${N(Math.round(x*100)/100)} ч, вторая — ${N(Math.round(y*100)/100)} ч, третья — ${N(Math.round(z*100)/100)} ч). Представь: если бы работали «две пары» сразу — все три пары одновременно, — каждая труба работала бы дважды, и бассейн наполнился бы вдвое быстрее, чем у трёх труб. Вот откуда деление на 2.`};},true);
G(8,()=>{const a=R(1,6);const t1=F(`x² + ${a*a}`,a===1?'x':a+'x'),t2=F(a===1?'x':a+'x',`x² + ${a*a}`);
// brute-force verify: only x=a on a fine grid
let cnt=0;for(let x=-30;x<=30;x+=0.25){if(x===0)continue;const t=(x*x+a*a)/(a*x);if(near(t+1/t,2.5))cnt++;}ok(cnt===1,'only a');
return {type:'set',q:`Реши уравнение ${M(t1+' + '+t2+' = '+F(5,2))}.`,ans:[a],ph:'корни через «;» или ∅',
hint:`Замена t = ${t1}. А потом вспомни: при x > 0 сумма «число + обратное» ≥ 2.`,
short:`t = 2 или t = ${F(1,2)}; t = ${F(1,2)} корней не даёт. x = ${a}.`,
explain:`Пусть t = ${t1}. Тогда t + ${F(1,'t')} = ${F(5,2)} → t = 2 или t = ${F(1,2)}.<br>• t = 2: x² + ${a*a} = ${2*a}x → (x − ${a})² = 0 → x = ${a}.<br>• t = ${F(1,2)}: 2x² + ${2*a*a} = ${cx(a)}x → 2x² − ${cx(a)}x + ${2*a*a} = 0, D = ${a*a} − ${16*a*a} &lt; 0 — корней нет.<br>Ответ: <b>${a}</b>.`,
explain2:`Быстрая оценка: ${t1} = ${F('x',a)} + ${F(a,'x')} — «число плюс обратное». Его модуль всегда ≥ 2, поэтому t = ${F(1,2)} невозможно сразу. Остаётся t = 2, а это ровно при ${F('x',a)} = 1, т. е. x = ${a}.`};},true);
G(8,()=>{const k=R(1,9);
return {type:'set',q:`При каких значениях параметра a уравнение ${M(F(`x² − ${k*k}`,'x − a')+' = 0')} имеет <b>ровно один</b> корень? Запиши все такие a.`,ans:[k,-k],ph:'значения a через «;»',
hint:`Числитель даёт два кандидата: ±${k}. Когда один из них «выбывает»?`,
short:`Кандидаты x = ±${k}; один выбывает, если a = ${k} или a = −${k}.`,
explain:`Числитель = 0 при x = ${k} и x = −${k}. Знаменатель запрещает x = a.<br>• Если a не равно ±${k} — оба корня подходят: два корня.<br>• Если a = ${k} — выбывает x = ${k}, остаётся один корень −${k}.<br>• Если a = −${k} — выбывает −${k}, остаётся ${k}.<br>Ответ: <b>a = ${k}; −${k}</b>.`,
explain2:`Подставь, например, a = 0: ${F(`x² − ${k*k}`,'x')} = 0 → x = ±${k}, два корня — не подходит. a = ${k}: ${F(`(x − ${k})(x + ${k})`,`x − ${k}`)} = 0 → только −${k} ✅. Параметр «ворует» корень, если совпадает с ним.`};},true);
const AVG=[];for(let a=10;a<=120;a+=5)for(let b=a+5;b<=150;b+=5){const t=2*a*b/(a+b);if(isInt(t))AVG.push([a,b,t]);}
G(8,()=>{const [a,b,t]=pick(AVG);const who=pick(['Марсоход','Дрон-доставщик','Электросамокат','Гоночный болид']);ok(near(2/(1/a+1/b),t),'avg');
return {type:'num',q:`${who} проехал первую половину пути со скоростью ${a} км/ч, а вторую — со скоростью ${b} км/ч. Найди среднюю скорость на всём пути (км/ч).`,ans:t,
hint:'Средняя скорость = весь путь : всё время. Обозначь половину пути буквой S.',
short:`${F(`2·${a}·${b}`,`${a} + ${b}`)} = ${t} км/ч.`,
explain:`Пусть половина пути S. Время: ${F('S',a)} + ${F('S',b)} = ${F(`${a+b}S`,a*b)}.<br>Средняя скорость = ${F('2S',`${F(`${a+b}S`,a*b)}`)} = ${F(`2·${a*b}`,a+b)} = <b>${t} км/ч</b>.<div class="box err"><b>Ловушка</b>(${a} + ${b}) : 2 = ${N((a+b)/2)} — неверно! На медленной половине ${who.toLowerCase()} едет <b>дольше</b>, и она «весит» больше.</div>`,
explain2:`Возьми конкретный путь: половина = ${a*b/gcd(a,b)} км. Первая половина: ${a*b/gcd(a,b)} : ${a} = ${b/gcd(a,b)} ч. Вторая: ${a*b/gcd(a,b)} : ${b} = ${a/gcd(a,b)} ч. Весь путь ${2*a*b/gcd(a,b)} км за ${(a+b)/gcd(a,b)} ч → ${t} км/ч ✅.`};},true);

/* ---------- widget: river ---------- */
function onTheory(root){
  const w=root.querySelector('#w-river');if(!w)return;
  w.innerHTML=`<b>Поиграй с рекой</b> (путь туда и обратно по 60 км)
  <label>Собственная скорость v: <input type="range" id="rv" min="4" max="30" value="12"><output id="rvo"></output></label>
  <label>Скорость течения u: <input type="range" id="ru" min="0" max="10" value="3"><output id="ruo"></output></label>
  <div id="rout" style="margin-top:6px;line-height:1.7"></div>`;
  const rv=w.querySelector('#rv'),ru=w.querySelector('#ru');
  const upd=()=>{const v=+rv.value,u=+ru.value;w.querySelector('#rvo').textContent=v+' км/ч';w.querySelector('#ruo').textContent=u+' км/ч';
    const f=x=>N(Math.round(x*100)/100);let h=`По течению: ${v} + ${u} = <b>${v+u} км/ч</b>, время 60 : ${v+u} = <b>${f(60/(v+u))} ч</b><br>`;
    if(v<=u)h+=`Против течения: ${v} − ${u} = ${v-u} км/ч — <b>лодку унесёт течением</b>, домой не вернуться! 🌊`;
    else{const T=60/(v+u)+60/(v-u);h+=`Против течения: ${v} − ${u} = <b>${v-u} км/ч</b>, время 60 : ${v-u} = <b>${f(60/(v-u))} ч</b><br>Всего: <b>${f(T)} ч</b>. В стоячей воде было бы 120 : ${v} = ${f(120/v)} ч${u>0?` — течение «съело» ${f(T-120/v)} ч`:''}.`;}
    w.querySelector('#rout').innerHTML=h;};
  rv.oninput=upd;ru.oninput=upd;upd();
}

